package buzz.walnutnest.bridge;
import android.accessibilityservice.AccessibilityService; import android.accessibilityservice.GestureDescription; import android.graphics.Path; import android.os.Bundle; import android.view.accessibility.AccessibilityEvent; import android.view.accessibility.AccessibilityNodeInfo; import java.util.ArrayList; import java.util.List;
public final class WalnutAccessibilityService extends AccessibilityService { private static volatile WalnutAccessibilityService instance; private BridgeHttpServer bridgeServer; public static WalnutAccessibilityService get(){return instance;} @Override protected void onServiceConnected(){super.onServiceConnected();instance=this;BridgeState.mark(this,"accessibility connected",null);try{bridgeServer=new BridgeHttpServer(this);bridgeServer.start();}catch(Throwable error){BridgeState.mark(this,"startup failed",error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage()));}} @Override public void onDestroy(){if(bridgeServer!=null){bridgeServer.stop();bridgeServer=null;}if(instance==this)instance=null;super.onDestroy();} @Override public void onAccessibilityEvent(AccessibilityEvent event){} @Override public void onInterrupt(){}
public List<AccessibilityNodeInfo> findText(String text){AccessibilityNodeInfo root=getRootInActiveWindow();return root==null?new ArrayList<>():root.findAccessibilityNodeInfosByText(text);} public boolean clickText(String text){for(AccessibilityNodeInfo node:findText(text)){AccessibilityNodeInfo current=node;while(current!=null){if(current.isClickable()&&current.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;current=current.getParent();}}return false;} public boolean setFocusedText(String text){AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null)return false;AccessibilityNodeInfo focused=root.findFocus(AccessibilityNodeInfo.FOCUS_INPUT);if(focused==null)return false;Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);return focused.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args);} public boolean swipe(float x1,float y1,float x2,float y2,long durationMs){Path path=new Path();path.moveTo(x1,y1);path.lineTo(x2,y2);GestureDescription.StrokeDescription stroke=new GestureDescription.StrokeDescription(path,0,Math.max(1,durationMs));return dispatchGesture(new GestureDescription.Builder().addStroke(stroke).build(),null,null);} }
